<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
      background: #f4f5f7;
      min-height: 100vh;
      padding: 24px;
    }
    .board {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      max-width: 1200px;
      margin: 0 auto;
    }
    .column {
      background: #ebecf0;
      border-radius: 12px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      min-height: 600px;
    }
    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 12px;
      padding: 0 4px;
    }
    .column-header h2 {
      font-size: 14px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: #172b4d;
    }
    .column-header .count {
      background: #0052cc;
      color: white;
      font-size: 12px;
      font-weight: 600;
      padding: 2px 8px;
      border-radius: 12px;
      min-width: 24px;
      text-align: center;
    }
    .card-list {
      flex: 1;
      min-height: 200px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
    }
    .card-list.drag-over {
      background: rgba(0, 82, 204, 0.1);
      border-radius: 8px;
    }
    .card {
      background: white;
      border-radius: 8px;
      padding: 12px;
      box-shadow: 0 1px 2px rgba(9, 30, 66, 0.15);
      cursor: grab;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 8px;
      transition: box-shadow 0.15s ease, transform 0.15s ease;
      user-select: none;
    }
    .card:hover {
      box-shadow: 0 4px 8px rgba(9, 30, 66, 0.15);
      transform: translateY(-1px);
    }
    .card:active, .card.dragging {
      cursor: grabbing;
      box-shadow: 0 8px 16px rgba(9, 30, 66, 0.2);
      transform: translateY(-2px);
    }
    .card.dragging {
      opacity: 0.5;
    }
    .card-title {
      flex: 1;
      font-size: 14px;
      line-height: 1.4;
      color: #172b4d;
      word-break: break-word;
    }
    .card-del {
      flex-shrink: 0;
      width: 24px;
      height: 24px;
      border: none;
      background: transparent;
      color: #6b778c;
      border-radius: 4px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.15s ease, color 0.15s ease;
      font-size: 18px;
      line-height: 1;
      padding: 0;
    }
    .card-del:hover {
      background: #ffebe9;
      color: #de350b;
    }
    .add-card-form {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
      max-width: 1200px;
      margin-left: auto;
      margin-right: auto;
    }
    #new-card {
      flex: 1;
      padding: 12px 16px;
      border: 2px solid #dfe1e6;
      border-radius: 8px;
      font-size: 14px;
      font-family: inherit;
      transition: border-color 0.15s ease, box-shadow 0.15s ease;
    }
    #new-card:focus {
      outline: none;
      border-color: #0052cc;
      box-shadow: 0 0 0 3px rgba(0, 82, 204, 0.15);
    }
    #add-card {
      padding: 12px 24px;
      background: #0052cc;
      color: white;
      border: none;
      border-radius: 8px;
      font-size: 14px;
      font-weight: 600;
      font-family: inherit;
      cursor: pointer;
      transition: background 0.15s ease;
    }
    #add-card:hover {
      background: #0065ff;
    }
    #add-card:active {
      background: #0043a3;
    }
    @media (max-width: 900px) {
      .board { grid-template-columns: 1fr; }
      .column { min-height: 300px; }
    }
  </style>
</head>
<body>
  <form class="add-card-form" id="add-form">
    <input type="text" id="new-card" placeholder="Enter card title..." autocomplete="off">
    <button type="submit" id="add-card">Add Card</button>
  </form>

  <div class="board" id="board">
    <section class="column" id="col-todo" data-column="todo">
      <header class="column-header">
        <h2>To Do</h2>
        <span class="count">0</span>
      </header>
      <div class="card-list" id="list-todo"></div>
    </section>
    <section class="column" id="col-doing" data-column="doing">
      <header class="column-header">
        <h2>Doing</h2>
        <span class="count">0</span>
      </header>
      <div class="card-list" id="list-doing"></div>
    </section>
    <section class="column" id="col-done" data-column="done">
      <header class="column-header">
        <h2>Done</h2>
        <span class="count">0</span>
      </header>
      <div class="card-list" id="list-done"></div>
    </section>
  </div>

  <script>
    const STORAGE_KEY = 'kanban-board-state';
    let cards = [];
    let dragSrc = null;

    function generateId() {
      return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
    }

    function loadState() {
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          cards = JSON.parse(stored);
        }
      } catch (e) {
        cards = [];
      }
      render();
    }

    function saveState() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
    }

    function createCardElement(card) {
      const el = document.createElement('div');
      el.className = 'card';
      el.draggable = true;
      el.dataset.id = card.id;
      el.innerHTML = `
        <span class="card-title">${escapeHtml(card.title)}</span>
        <button class="card-del" aria-label="Delete card" type="button">×</button>
      `;
      el.querySelector('.card-del').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteCard(card.id);
      });
      el.addEventListener('dragstart', handleDragStart);
      el.addEventListener('dragend', handleDragEnd);
      return el;
    }

    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    function render() {
      ['todo', 'doing', 'done'].forEach(col => {
        const list = document.getElementById(`list-${col}`);
        const count = document.querySelector(`#col-${col} .count`);
        const colCards = cards.filter(c => c.column === col);
        list.innerHTML = '';
        colCards.forEach(card => {
          list.appendChild(createCardElement(card));
        });
        count.textContent = colCards.length;
      });
      setupDropZones();
    }

    function setupDropZones() {
      document.querySelectorAll('.card-list').forEach(list => {
        list.removeEventListener('dragover', handleDragOver);
        list.removeEventListener('drop', handleDrop);
        list.removeEventListener('dragleave', handleDragLeave);
        list.addEventListener('dragover', handleDragOver);
        list.addEventListener('drop', handleDrop);
        list.addEventListener('dragleave', handleDragLeave);
      });
    }

    function handleDragStart(e) {
      dragSrc = this;
      this.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', this.dataset.id);
    }

    function handleDragEnd(e) {
      this.classList.remove('dragging');
      document.querySelectorAll('.card-list').forEach(list => list.classList.remove('drag-over'));
      dragSrc = null;
    }

    function handleDragOver(e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      this.classList.add('drag-over');
    }

    function handleDragLeave(e) {
      if (!this.contains(e.relatedTarget)) {
        this.classList.remove('drag-over');
      }
    }

    function handleDrop(e) {
      e.preventDefault();
      this.classList.remove('drag-over');
      const cardId = e.dataTransfer.getData('text/plain');
      const targetColumn = this.id.replace('list-', '');
      moveCard(cardId, targetColumn);
    }

    function addCard(title) {
      const trimmed = title.trim();
      if (!trimmed) return;
      const card = { id: generateId(), title: trimmed, column: 'todo' };
      cards.push(card);
      saveState();
      render();
    }

    function deleteCard(id) {
      cards = cards.filter(c => c.id !== id);
      saveState();
      render();
    }

    function moveCard(id, targetColumn) {
      const card = cards.find(c => c.id === id);
      if (card && card.column !== targetColumn) {
        card.column = targetColumn;
        saveState();
        render();
      }
    }

    document.getElementById('add-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const input = document.getElementById('new-card');
      addCard(input.value);
      input.value = '';
      input.focus();
    });

    loadState();
  </script>
</body>
</html>
